import React, { useState, useEffect } from "react";
import styled from "styled-components";
import EngineerAdd from "../components/EngineerAdd";
import { apiAllUsers } from "../service/user";

const Container = styled.div`
  margin-top: 50px;
  display: flex;
  justify-content: center;
  flex-direction: column;
  align-items: center;
`;

const Wrapper = styled.div`
  width: 90%;
  position: relative;
`;

const Title = styled.h2`
  margin-bottom: 30px;
  font-size: 40px;
  font-weight: bold;
  text-align: center;
  color: #1e3a8a
`;

const AddEngineerButton = styled.button`
  position: absolute;
  top: 20px;
  right: 20px;
  padding: 10px 20px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 16px;
  transition: background-color 0.3s;
  margin: 20px 10px;
  &:hover {
    background-color: #0056b3;
  }
`;

const EngineersContainer = styled.div`
  margin-top: 70px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  justify-items: center;
`;

const EngineerCard = styled.div`
  display: flex;
  flex-direction: column;
  background-color: ${(props) => (props.role === "ADMIN" ? "#cce5ff" : "#f9f9f9")}; // Background xanh dương cho ADMIN
  padding: 20px;
  width: 390px;
  border: 1px solid #ddd;
  border-radius: 8px;
  text-align: center;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const EngineerAvatar = styled.div`
  width: 100px;
  height: 100px;
  border-radius: 50%;
  margin-bottom: 15px;
  overflow: hidden;
  margin-left: auto;
  margin-right: auto;
  background-image: url(${(props) => props.src});
  background-size: cover;
  background-position: center;
`;

const EngineerRole = styled.div`
  font-weight: bold;
  color: ${(props) => (props.role === "ADMIN" ? "#007bff" : "#555")}; // Màu sắc khác cho ADMIN
  margin-top: 10px;
`;

const EngineerField = styled.div`
  margin: 8px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const EngineerLabel = styled.span`
  font-weight: bold;
  color: #555;
  width: 100px;
  text-align: left;
`;

const EngineerLabel1 = styled.span`
  font-weight: bold;
  color: #555;
  width: 80px;
  margin: 0 0 0 20px;
  text-align: left;
`;

const EngineerValue = styled.span`
  color: #333;
  flex: 1;
  text-align: left;
  width: 200px;
`;

const Engineers = () => {
  const [showModal, setShowModal] = useState(false); 
  const [engineersData, setEngineersData] = useState([]);

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const response = await apiAllUsers();
        setEngineersData(response.data);
      } catch (error) {
        console.error("Lỗi khi tải dữ liệu người dùng:", error);
      }
    };

    fetchUsers();
  }, []);

  const closeModal = () => {
    setShowModal(false);
  };

  return (
    <Container>
      <Wrapper>
        <Title>Danh sách kỹ sư</Title>
        <AddEngineerButton onClick={() => setShowModal(true)}>Thêm Kỹ sư</AddEngineerButton>
        <EngineerAdd showModal={showModal} closeModal={closeModal} />
        <EngineersContainer>
          {engineersData.map((engineer, index) => (
            <EngineerCard key={index} role={engineer.role}> {/* Truyền role vào để thay đổi màu nền */}
              <EngineerAvatar
                src={
                  engineer.gender === "Nam"
                    ? "/default_avatar_male.jpg"
                    : "/default_avatar_female.jpg"
                }
              />
              <EngineerRole role={engineer.role}>{engineer.role}</EngineerRole> {/* Hiển thị role dưới avatar */}
              <EngineerField>
                <EngineerLabel>Họ và tên:</EngineerLabel>
                <EngineerValue>{engineer.username}</EngineerValue>
                <EngineerLabel1>Giới tính:</EngineerLabel1>
                <EngineerValue>{engineer.gender}</EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Số điện thoại:</EngineerLabel>
                <EngineerValue>{engineer.phone}</EngineerValue>
                <EngineerLabel1>Năm sinh:</EngineerLabel1>
                <EngineerValue>
                  {new Date(engineer.birthday).toLocaleString("vi-VN", {
                    day: "2-digit",
                    month: "2-digit",
                    year: "numeric",
                  })}
                </EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Email:</EngineerLabel>
                <EngineerValue>{engineer.email}</EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Địa chỉ:</EngineerLabel>
                <EngineerValue>{engineer.address}</EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Nghề Nghiệp:</EngineerLabel>
                <EngineerValue>{engineer.career}</EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Nơi làm việc:</EngineerLabel>
                <EngineerValue>{engineer.workplace}</EngineerValue>
              </EngineerField>
            </EngineerCard>
          ))}
        </EngineersContainer>
      </Wrapper>
    </Container>
  );
};

export default Engineers;
